from pathlib import Path
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
RESULTS = ROOT / "results" / "experiments"


def test_model_comparison_has_expected_models_and_horizons():
    path = RESULTS / "model_comparison.csv"
    if not path.exists():
        # The comparison is generated by scripts/compare_experiments.py.
        return
    frame = pd.read_csv(path)
    assert {"Model", "Horizon (minutes)", "MAE", "RMSE", "Valid targets"}.issubset(frame.columns)
    assert set(frame["Model"]) >= {"Persistence", "Centralized shared GRU", "FedAvg GRU"}
    assert set(frame["Horizon (minutes)"]) == {15, 30, 60}


def test_fedavg_round_curve_is_monotonic_in_logged_validation_mae():
    path = RESULTS / "fedavg_round_metrics.csv"
    if not path.exists():
        return
    frame = pd.read_csv(path).sort_values("round")
    assert len(frame) == 10
    assert frame["round"].tolist() == list(range(1, 11))
    assert frame["val_mae_normalized"].notna().all()
    assert frame["val_mae_normalized"].iloc[-1] < frame["val_mae_normalized"].iloc[0]
